Usage example: BlueGreenConfigcfg;
BlueGreenDeploymentbg(hot_reload_engine,cfg);

//1.Deploynewversiontostandby(green)slot
autoresult=bg.deployToStandby("1.6.0");
if(!result.success){handle_error();}

//2.Runhealthchecksonthestandbyslot
//...

//3.Promotestandbytoactive
if(!bg.promote()){handle_promotion_failure();}

//4.Observepost-promotionhealthevents
bg.reportSuccess();
bg.reportError();

//5.Rollbackifneeded
if(bg.shouldRollback()){bg.rollback("errorratetoohigh");}
